public int partition(String topic, Object key,
    byte[] keyBytes, Object value, byte[] valueBytes,
    Cluster cluster) {
  String keyStr = (String) key;
  if (keyStr.startsWith("VIP_"))
    return 0;
  return Math.abs(keyStr.hashCode()) %
    (cluster.partitionCountForTopic(topic) - 1) + 1;
}

